})
EOF
cat > modules/newsletter/Http/NewsletterController.ts <<'EOF'
import { Controller, ValidationException } from '@guren/core'
import { Subscription } from '../Subscription.js'
import { ConfirmTokenParamSchema, SubscriptionEmailSchema } from './validators.js'

export default class NewsletterController extends Controller {
  async subscribe(): Promise<Response> {
    const { email } = await this.validateBody(SubscriptionEmailSchema)

    const existing = await Subscription.where({ email })
    if (existing.length > 0) {
      throw ValidationException.withMessages({ email: 'This email address is already subscribed.' })
    }

    const token = `${crypto.randomUUID()}${crypto.randomUUID()}`.replaceAll('-', '')
    await Subscription.forceCreate({ email, token, confirmedAt: null })

    return this.redirect(this.backUrl())
  }

  async confirm(): Promise<Response> {
    const { token } = this.validateParams(ConfirmTokenParamSchema)

    const [subscription] = await Subscription.where({ token })
    if (!subscription) {
      return this.json({ message: 'Not found.' }, { status: 404 })
    }

    await Subscription.update({ id: subscription.id }, { confirmedAt: new Date().toISOString() })

    return this.redirect('/')
  }

  async unsubscribe(): Promise<Response> {
    const { email } = await this.validateBody(SubscriptionEmailSchema)

    await Subscription.delete({ email })

    return this.redirect(this.backUrl())
  }

  // Only a same-site Referer is honoured, so the redirect cannot leave the site.
  private backUrl(): string {
    const referer = this.request.header('referer')
    if (!referer) return '/'

    try {
      const target = new URL(referer)
      if (target.host !== new URL(this.request.url).host) return '/'
      return `${target.pathname}${target.search}`
    } catch {
      return '/'
    }
  }
}
EOF
cat > modules/newsletter/routes.ts <<'EOF'
import type { Router } from '@guren/core'
import NewsletterController from './Http/NewsletterController.js'
import { SubscriptionEmailSchema } from './Http/validators.js'

export function registerNewsletterRoutes(router: Router): void {
  router.post('/subscribe', { name: 'newsletter.subscribe', body: SubscriptionEmailSchema }, [NewsletterController, 'subscribe'])
  router.get('/confirm/:token', [NewsletterController, 'confirm']).name('newsletter.confirm')
  router.post('/unsubscribe', { name: 'newsletter.unsubscribe', body: SubscriptionEmailSchema }, [NewsletterController, 'unsubscribe'])
}
EOF
